// Browser demo for fit_dart_sdk: decodes a FIT file in the page, with no server
// and no upload. Hand-written and local to this repository — unlike lib/ one
// directory up, none of this is generated by fitgen, so it is safe to edit.
//
// Built by `flutter build web` into build/web, which is what the gh-pages
// workflow publishes.

import 'dart:convert';
import 'dart:typed_data';

import 'package:fit_dart_sdk/fit_dart_sdk.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart' show rootBundle;

import 'src/browser.dart';
import 'src/decoded_file.dart';
import 'src/field_values.dart';
import 'src/theme.dart';
import 'src/widgets/drop_zone.dart';
import 'src/widgets/error_panel.dart';
import 'src/widgets/message_table.dart';
import 'src/widgets/panel.dart';
import 'src/widgets/series_chart.dart';
import 'src/widgets/summary_cards.dart';
import 'src/widgets/track_view.dart';

const String repositoryUrl = 'https://github.com/glandais/fit-dart-sdk';

void main() => runApp(const DemoApp());

class DemoApp extends StatelessWidget {
  const DemoApp({super.key});

  @override
  Widget build(BuildContext context) => MaterialApp(
        title: 'FIT decoder — fit_dart_sdk',
        debugShowCheckedModeBanner: false,
        theme: demoTheme(Brightness.light),
        darkTheme: demoTheme(Brightness.dark),
        home: const DemoPage(),
      );
}

class DemoPage extends StatefulWidget {
  const DemoPage({super.key});

  @override
  State<DemoPage> createState() => _DemoPageState();
}

class _DemoPageState extends State<DemoPage> {
  DecodedFile? _file;
  String _status = 'Ready.';
  bool _statusIsError = false;
  bool _busy = false;
  bool _dragging = false;
  bool _includeUnknown = false;
  String? _selectedType;

  @override
  void initState() {
    super.initState();
    listenForDroppedFiles(
      onDragOver: (over) {
        if (over != _dragging) setState(() => _dragging = over);
      },
      onFile: (file) => _decode(file.name, file.bytes),
    );
  }

  Future<void> _choose() async {
    final picked = await chooseFitFile();
    if (picked != null) await _decode(picked.name, picked.bytes);
  }

  Future<void> _loadSample() async {
    setState(() {
      _busy = true;
      _status = 'Loading the sample activity…';
      _statusIsError = false;
    });
    final data = await rootBundle.load('assets/sample-activity.fit');
    await _decode('sample-activity.fit', data.buffer.asUint8List());
  }

  Future<void> _decode(String name, Uint8List bytes) async {
    if (!FitDecoder(bytes).isFit()) {
      setState(() {
        _busy = false;
        _status = '$name does not start with a FIT header.';
        _statusIsError = true;
      });
      return;
    }

    setState(() {
      _busy = true;
      _status = 'Decoding $name…';
      _statusIsError = false;
    });

    final decoded = await DecodedFile.decode(
      name,
      bytes,
      includeUnknownData: _includeUnknown,
    );
    if (!mounted) return;

    setState(() {
      _file = decoded;
      _selectedType = decoded.byType.keys.firstOrNull;
      _busy = false;
      _statusIsError = false;
      _status = '$name — ${formatCount(decoded.result.mesgs.length)} messages '
          'decoded in ${decoded.elapsed.inMilliseconds} ms';
    });
  }

  /// Unknown data changes what the decoder keeps, so it means decoding again.
  Future<void> _setIncludeUnknown(bool value) async {
    setState(() => _includeUnknown = value);
    final file = _file;
    if (file != null) await _decode(file.name, file.bytes);
  }

  void _downloadJson() {
    final file = _file;
    if (file == null) return;

    final payload = <String, Object?>{
      'file': file.name,
      'profileVersion': file.result.profileVersion,
      'errors': [
        for (final error in file.result.errors)
          {'message': error.message, 'bytePosition': error.bytePosition},
      ],
      'messages': [
        for (final mesg in file.result.mesgs)
          {
            'name': mesg.mesgName,
            'num': mesg.globalMesgNum,
            'index': mesg.decoderMesgIndex,
            'fields': {
              for (final field in fieldValuesOf(mesg))
                if (!field.developer) field.name: jsonValue(field.value),
            },
            'developerFields': {
              for (final field in fieldValuesOf(mesg))
                if (field.developer) field.name: jsonValue(field.value),
            },
          },
      ],
    };

    saveTextFile(
      '${file.name.replaceAll(RegExp(r'\.fit$', caseSensitive: false), '')}.json',
      const JsonEncoder.withIndent('  ').convert(payload),
      'application/json',
    );
  }

  @override
  Widget build(BuildContext context) {
    final colors = DemoColors.of(context);
    final file = _file;

    return Scaffold(
      body: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          const _TopBar(),
          Expanded(
            child: SingleChildScrollView(
              padding: const EdgeInsets.fromLTRB(20, 20, 20, 40),
              child: Center(
                child: ConstrainedBox(
                  constraints: const BoxConstraints(maxWidth: 1200),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      DropZone(
                        dragging: _dragging,
                        busy: _busy,
                        status: _status,
                        statusIsError: _statusIsError,
                        onChoose: _choose,
                        onSample: _loadSample,
                      ),
                      if (file != null) ...[
                        const SizedBox(height: 20),
                        SummaryCards(file: file),
                        if (file.result.errors.isNotEmpty) ...[
                          const SizedBox(height: 20),
                          ErrorPanel(errors: file.result.errors),
                        ],
                        const SizedBox(height: 20),
                        _TrackAndSeries(
                            file: file, onSeriesChanged: () => setState(() {})),
                        const SizedBox(height: 20),
                        Panel(
                          title: 'Messages',
                          trailing: _MessageActions(
                            includeUnknown: _includeUnknown,
                            onIncludeUnknown: _busy ? null : _setIncludeUnknown,
                            onDownload: _downloadJson,
                          ),
                          child: MessageTable(
                            byType: file.byType,
                            selected: _selectedType ?? '',
                            onSelect: (name) =>
                                setState(() => _selectedType = name),
                          ),
                        ),
                      ],
                      const SizedBox(height: 28),
                      DefaultTextStyle(
                        style: TextStyle(fontSize: 12.5, color: colors.inkSoft),
                        child: const _Footer(),
                      ),
                    ],
                  ),
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }
}

class _TopBar extends StatelessWidget {
  const _TopBar();

  @override
  Widget build(BuildContext context) {
    final colors = DemoColors.of(context);
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 16),
      decoration: BoxDecoration(
        color: colors.panel,
        border: Border(bottom: BorderSide(color: colors.line)),
      ),
      child: Wrap(
        alignment: WrapAlignment.spaceBetween,
        crossAxisAlignment: WrapCrossAlignment.center,
        runSpacing: 12,
        spacing: 16,
        children: [
          Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Container(
                width: 44,
                height: 44,
                alignment: Alignment.center,
                decoration: BoxDecoration(
                  color: colors.accent,
                  borderRadius: const BorderRadius.all(Radius.circular(10)),
                ),
                child: Text(
                  'FIT',
                  style: TextStyle(
                    color: colors.onAccent,
                    fontWeight: FontWeight.w700,
                    letterSpacing: 0.5,
                  ),
                ),
              ),
              const SizedBox(width: 14),
              Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    'FIT decoder',
                    style: TextStyle(
                      fontSize: 20,
                      fontWeight: FontWeight.w600,
                      color: colors.ink,
                    ),
                  ),
                  const SizedBox(height: 2),
                  Text(
                    'fit_dart_sdk in a Flutter web app. Everything runs in this '
                    'page — no upload, no server.',
                    style: TextStyle(fontSize: 13, color: colors.inkSoft),
                  ),
                ],
              ),
            ],
          ),
          Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Pill('FIT profile ${Profile.versionMajor}.${Profile.versionMinor}'
                  '.${Profile.versionBuild}'),
              const SizedBox(width: 8),
              Pill(
                'GitHub',
                icon: Icons.open_in_new,
                onTap: () => openUrl(repositoryUrl),
              ),
            ],
          ),
        ],
      ),
    );
  }
}

class _TrackAndSeries extends StatelessWidget {
  const _TrackAndSeries({required this.file, required this.onSeriesChanged});

  final DecodedFile file;
  final VoidCallback onSeriesChanged;

  @override
  Widget build(BuildContext context) {
    final colors = DemoColors.of(context);

    final track = Panel(
      title: 'Track',
      trailing: Text(
        file.track.isEmpty
            ? 'no position data'
            : '${formatCount(file.track.length)} points',
        textAlign: TextAlign.right,
        style: TextStyle(fontSize: 12.5, color: colors.inkSoft),
      ),
      child: SizedBox(height: 260, child: TrackView(points: file.track)),
    );

    final series = Panel(
      title: 'Series',
      trailing: SeriesToggles(series: file.series, onChanged: onSeriesChanged),
      child: SizedBox(height: 260, child: SeriesChart(series: file.series)),
    );

    return LayoutBuilder(
      builder: (context, constraints) => constraints.maxWidth < 820
          ? Column(children: [track, const SizedBox(height: 20), series])
          : Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Expanded(child: track),
                const SizedBox(width: 20),
                Expanded(child: series),
              ],
            ),
    );
  }
}

class _MessageActions extends StatelessWidget {
  const _MessageActions({
    required this.includeUnknown,
    required this.onIncludeUnknown,
    required this.onDownload,
  });

  final bool includeUnknown;
  final ValueChanged<bool>? onIncludeUnknown;
  final VoidCallback onDownload;

  @override
  Widget build(BuildContext context) {
    final colors = DemoColors.of(context);
    return Wrap(
      alignment: WrapAlignment.end,
      crossAxisAlignment: WrapCrossAlignment.center,
      spacing: 12,
      runSpacing: 8,
      children: [
        MouseRegion(
          cursor: SystemMouseCursors.click,
          child: GestureDetector(
            onTap: onIncludeUnknown == null
                ? null
                : () => onIncludeUnknown!(!includeUnknown),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                SizedBox(
                  width: 20,
                  height: 20,
                  child: Checkbox(
                    value: includeUnknown,
                    onChanged: onIncludeUnknown == null
                        ? null
                        : (value) => onIncludeUnknown!(value ?? false),
                  ),
                ),
                const SizedBox(width: 8),
                Text(
                  'include unknown data',
                  style: TextStyle(fontSize: 13, color: colors.ink),
                ),
              ],
            ),
          ),
        ),
        OutlinedButton(
          onPressed: onDownload,
          style: OutlinedButton.styleFrom(
            foregroundColor: colors.ink,
            side: BorderSide(color: colors.line),
            padding: const EdgeInsets.symmetric(horizontal: 14),
          ),
          child: const Text('Download JSON'),
        ),
      ],
    );
  }
}

class _Footer extends StatelessWidget {
  const _Footer();

  @override
  Widget build(BuildContext context) {
    final colors = DemoColors.of(context);
    return Wrap(
      alignment: WrapAlignment.center,
      children: [
        const Text('Decoded by '),
        MouseRegion(
          cursor: SystemMouseCursors.click,
          child: GestureDetector(
            onTap: () => openUrl(repositoryUrl),
            child: Text('fit_dart_sdk', style: TextStyle(color: colors.accent)),
          ),
        ),
        const Text(
          ', generated from the Garmin FIT profile. '
          'FIT is a trademark of Garmin International, Inc.',
        ),
      ],
    );
  }
}
